#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> A, B;  // 1-indexed: A[i] = a_i, B[i] = b_i

// Can k friends be invited? Scan richest -> poorest; the j-th invited friend
// (j = cnt, friends richer than it already invited) is valid iff
// cnt <= a_i and k-1-cnt <= b_i.
bool ok(int k) {
    int cnt = 0;
    for (int i = n; i >= 1 && cnt < k; i--) {
        if (cnt <= A[i] && k - 1 - cnt <= B[i]) cnt++;
    }
    return cnt == k;
}

int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        scanf("%d", &n);
        A.assign(n + 1, 0);
        B.assign(n + 1, 0);
        for (int i = 1; i <= n; i++) scanf("%d %d", &A[i], &B[i]);
        int lo = 0, hi = n;  // k = 0 is always feasible; feasibility is monotone
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid;
            else hi = mid - 1;
        }
        printf("%d\n", lo);
    }
    return 0;
}

