#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, k;
        scanf("%d %d", &n, &k);
        vector<vector<int>> g(n + 1);
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            scanf("%d %d", &u, &v);
            g[u].push_back(v);
            g[v].push_back(u);
        }
        // BFS order from root 1
        vector<int> par(n + 1, 0), order;
        order.reserve(n);
        order.push_back(1);
        for (size_t h = 0; h < order.size(); h++) {
            int v = order[h];
            for (int u : g[v])
                if (u != par[v]) {
                    par[u] = v;
                    order.push_back(u);
                }
        }
        // down[v]: longest path from v into its subtree (in edges)
        vector<int> down(n + 1, 0), up(n + 1, 0), r(n + 1, 0);
        for (int h = n - 1; h >= 0; h--) {
            int v = order[h];
            if (par[v]) down[par[v]] = max(down[par[v]], down[v] + 1);
        }
        // up[v]: longest path from v going through its parent; rerooting
        for (int v : order) {
            int t1 = 0, t2 = 0, id1 = -1;  // two largest branch lengths (0 if missing)
            for (int u : g[v]) {
                int val = (u == par[v]) ? up[v] : down[u] + 1;
                if (val > t1) { t2 = t1; t1 = val; id1 = u; }
                else if (val > t2) t2 = val;
            }
            r[v] = t2 + 1;  // round in which v is removed
            for (int u : g[v])
                if (u != par[v]) up[u] = 1 + ((u == id1) ? t2 : t1);
        }
        int cnt = 0;
        for (int v = 1; v <= n; v++)
            if (r[v] > k) cnt++;
        printf("%d\n", cnt);
    }
    return 0;
}

