using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        vector<long long> neg, pos, zer;
        long long mx = LLONG_MIN, mn = LLONG_MAX;
        for (int i = 0; i < n; i++) {
            long long x;
            scanf("%lld", &x);
            mx = max(mx, x);
            mn = min(mn, x);
            if (x < 0) neg.push_back(x);
            else if (x > 0) pos.push_back(x);
            else zer.push_back(x);
        }
        if (mx == mn) {  // all equal, and sum 0 forces all zero
            puts("No");
            continue;
        }
        puts("Yes");
        // Greedy on prefix sums S: if S >= 0 take a negative, else take a positive.
        // Keeps mn <= S <= mx-1, so every subarray sum has |.| < mx - mn.
        size_t in = 0, ip = 0, iz = 0;
        long long S = 0;
        for (int step = 0; step < n; step++) {
            long long x;
            if (S >= 0 && in < neg.size()) x = neg[in++];
            else if (S >= 0) x = (iz < zer.size()) ? zer[iz++] : pos[ip++];
            else x = pos[ip++];
            S += x;
            printf("%lld ", x);
        }
        printf("\n");
    }
    return 0;
}

