int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    vector<long long> b11, b10, b01;
    for (int i = 0; i < n; i++) {
        long long t;
        int a, b;
        scanf("%lld %d %d", &t, &a, &b);
        if (a && b) b11.push_back(t);
        else if (a) b10.push_back(t);
        else if (b) b01.push_back(t);
    }
    sort(b11.begin(), b11.end());
    sort(b10.begin(), b10.end());
    sort(b01.begin(), b01.end());
    auto prefix = [](const vector<long long> &v) {
        vector<long long> p(v.size() + 1, 0);
        for (size_t i = 0; i < v.size(); i++) p[i + 1] = p[i] + v[i];
        return p;
    };
    auto p11 = prefix(b11), p10 = prefix(b10), p01 = prefix(b01);
    long long best = -1;
    // c = number of both-liked books taken (cheapest c); need the rest from each side
    for (int c = 0; c <= (int)b11.size(); c++) {
        int need = max(0, k - c);
        if (need > (int)b10.size() || need > (int)b01.size()) continue;
        long long cost = p11[c] + p10[need] + p01[need];
        if (best < 0 || cost < best) best = cost;
    }
    printf("%lld\n", best);
    return 0;
}

