int main() {
    int t;
    scanf("%d", &t);
    static char buf[200005];
    while (t--) {
        int n;
        scanf("%d", &n);
        scanf("%s", buf);
        string s(buf);
        int T = 0, Z = 0;  // T = number of 1s, Z = number of 0s
        for (char c : s) { if (c == '1') T++; else Z++; }
        if (T % 2 || Z % 2) { puts("NO"); continue; }
        // Feasibility: when the zero-count prefix is odd, the ones-walk must be >= 1
        // at that point, i.e. 1 <= c <= T-1 (c = ones so far).
        bool ok = true;
        int c = 0, k = 0;
        for (int i = 0; i < n && ok; i++) {
            if (s[i] == '1') c++; else k++;
            if (k % 2 == 1 && (c < 1 || c > T - 1)) ok = false;
        }
        if (!ok) { puts("NO"); continue; }
        string a(n, '('), b(n, '(');
        int j = 0, Y = 0;
        k = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == '1') {
                char ch = (j < T / 2) ? '(' : ')';  // ones walk: up first, then down
                a[i] = b[i] = ch;
                j++;
            } else {
                k++;
                int Ynew = (k % 2 == 1) ? 1 : 0;
                int d = Ynew - Y;
                Y = Ynew;
                a[i] = (d == 1) ? '(' : ')';
                b[i] = (d == 1) ? ')' : '(';
            }
        }
        puts("YES");
        puts(a.c_str());
        puts(b.c_str());
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, m;
        scanf("%d %d", &n, &m);
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        long long ops = 0;
        // Part 1: every suffix a[j+1..m] (j >= 1) must have sum <= 0.
        // Scan from m down to 2, negate the largest positive values when the sum is > 0.
        {
            priority_queue<long long> pq;
            long long cur = 0;
            for (int i = m; i >= 2; i--) {
                cur += a[i];
                pq.push(a[i]);
                while (cur > 0 && !pq.empty() && pq.top() > 0) {
                    long long v = pq.top();
                    pq.pop();
                    cur -= 2 * v;
                    ops++;
                }
            }
        }
        // Part 2: every prefix a[m+1..j] (j > m) must have sum >= 0.
        // Scan from m+1 to n, negate the most negative values when the sum is < 0.
        {
            priority_queue<long long, vector<long long>, greater<long long>> pq;
            long long cur = 0;
            for (int i = m + 1; i <= n; i++) {
                cur += a[i];
                pq.push(a[i]);
                while (cur < 0 && !pq.empty() && pq.top() < 0) {
                    long long v = pq.top();
                    pq.pop();
                    cur -= 2 * v;
                    ops++;
                }
            }
        }
        printf("%lld\n", ops);
    }
    return 0;
}

