            if (j >= od.size() || (i < ev.size() && ev[i] < od[j])) res.push_back(ev[i++]);
            else res.push_back(od[j++]);
        }
        puts(res.c_str());
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n;
vector<long long> h;  // 1-indexed

// Can the smallest final heap be at least X?
// Final heap j = h_j - 3*d_j + d_{j+1} + 2*d_{j+2}; step i needs 3*d_i <= h_i (h_i untouched before step i).
// Choose d_i from n down to 3 as large as possible while heap i stays >= X.
bool ok(long long X) {
    vector<long long> d(n + 3, 0);
    for (int i = n; i >= 3; i--) {
        long long num = h[i] + d[i + 1] + 2 * d[i + 2] - X;
        if (num < 0) return false;
        d[i] = min(h[i] / 3, num / 3);
    }
    return h[1] + 2 * d[3] >= X && h[2] + d[3] + 2 * d[4] >= X;
}

