    while (t--) {
        int n;
        scanf("%d", &n);
        vector<int> a(n);
        for (auto &x : a) scanf("%d", &x);
        // Levels are contiguous blocks of the BFS order. The next level can use at most
        // (size of previous level) increasing runs, since each parent takes one run.
        int ans = 0;
        int prevL = 0, prevR = 1;  // root level [0,1)
        int p = 1;
        while (p < n) {
            int sz = prevR - prevL;
            int runs = 1, q = p + 1;
            while (q < n) {
                int nr = runs + (a[q] < a[q - 1] ? 1 : 0);
                if (nr > sz) break;
                runs = nr;
                q++;
            }
            ans++;
            prevL = p;
            prevR = q;
            p = q;
        }
        printf("%d\n", ans);
    }
    return 0;
}

