int main() {
    int n;
    scanf("%d", &n);
    vector<int> a(n + 1, 0);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    // Gap values: every v strictly between a[i-1] and a[i] must already be present
    // before the mex jumps to a[i]; they are placed at earlier "equal" steps.
    vector<int> G;
    int prev = 0;
    for (int i = 1; i <= n; i++) {
        if (a[i] < prev) { puts("-1"); return 0; }
        for (int v = prev + 1; v < a[i]; v++) G.push_back(v);
        prev = a[i];
    }
    vector<char> placed(n + 2, 0);
    vector<int> b(n + 1, 0);
    size_t ptr = 0;
    prev = 0;
    for (int i = 1; i <= n; i++) {
        if (a[i] == prev) {
            if (ptr < G.size()) {
                b[i] = G[ptr];
                placed[G[ptr]] = 1;
                ptr++;
            } else {
                b[i] = 1000000;  // unused value above any mex
            }
        } else {
            for (int v = prev + 1; v < a[i]; v++)
                if (!placed[v]) { puts("-1"); return 0; }
            b[i] = prev;  // mex jumps from prev to a[i]
            placed[prev] = 1;
        }
        prev = a[i];
    }
    for (int i = 1; i <= n; i++) printf("%d%c", b[i], i == n ? '\n' : ' ');
    return 0;
}

