#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    const int NT = 6;
    // portal types as 2-bit masks: B=1, G=2, R=4, Y=8
    const int typeMask[NT] = {3, 5, 9, 6, 10, 12};  // BG, BR, BY, GR, GY, RY
    auto maskOf = [](const char *s) {
        int m = 0;
        for (int i = 0; s[i]; i++) {
            char c = s[i];
            m |= (c == 'B') ? 1 : (c == 'G') ? 2 : (c == 'R') ? 4 : 8;
        }
        return m;
    };
    while (t--) {
        int n, q;
        scanf("%d %d", &n, &q);
        vector<int> mk(n + 2, 0);
        static char buf[8];
        for (int i = 1; i <= n; i++) {
            scanf("%s", buf);
            mk[i] = maskOf(buf);
        }
        // Nearest city of each type to the left (<= i) and to the right (>= i); 0 / n+1 = none.
        vector<vector<int>> Lf(NT, vector<int>(n + 2, 0)), Rt(NT, vector<int>(n + 2, n + 1));
        for (int k = 0; k < NT; k++) {
            for (int i = 1; i <= n; i++)
                Lf[k][i] = (mk[i] == typeMask[k]) ? i : Lf[k][i - 1];
            for (int i = n; i >= 1; i--)
                Rt[k][i] = (mk[i] == typeMask[k]) ? i : Rt[k][i + 1];
        }
        while (q--) {
            int x, y;
            scanf("%d %d", &x, &y);
            if (x > y) swap(x, y);
            if (x == y) { puts("0"); continue; }
            if (mk[x] & mk[y]) { printf("%d\n", y - x); continue; }
            long long best = -1;
            for (int k = 0; k < NT; k++) {
                // z must share a color with x and with y (same as adjacency)
                if (!(typeMask[k] & mk[x]) || !(typeMask[k] & mk[y])) continue;
                int zl = Lf[k][x];
                if (zl >= 1) {
                    long long c = (long long)(x - zl) + (y - zl);
                    if (best < 0 || c < best) best = c;
                }
                int zr = Rt[k][x];
                if (zr <= n) {
                    long long c = (long long)(zr - x) + abs(zr - y);
                    if (best < 0 || c < best) best = c;
                }
            }
            printf("%lld\n", best);
        }
    }
    return 0;
}

#include <bits/stdc++.h>
