int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, m;
        scanf("%d %d", &n, &m);
        int N = n * m;
        vector<int> posA(N + 1), posB(N + 1);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                int v;
                scanf("%d", &v);
                posA[v] = i * m + j;
            }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                int v;
                scanf("%d", &v);
                posB[v] = i * m + j;
            }
        // Row map and column map must be consistent functions (and injective) over all values.
        vector<int> rowTo(n, -1), rowFrom(n, -1), colTo(m, -1), colFrom(m, -1);
        bool ok = true;
        for (int v = 1; v <= N && ok; v++) {
            int ra = posA[v] / m, ca = posA[v] % m;
            int rb = posB[v] / m, cb = posB[v] % m;
            if (rowTo[ra] == -1) rowTo[ra] = rb; else if (rowTo[ra] != rb) ok = false;
            if (rowFrom[rb] == -1) rowFrom[rb] = ra; else if (rowFrom[rb] != ra) ok = false;
            if (colTo[ca] == -1) colTo[ca] = cb; else if (colTo[ca] != cb) ok = false;
            if (colFrom[cb] == -1) colFrom[cb] = ca; else if (colFrom[cb] != ca) ok = false;
        }
        puts(ok ? "YES" : "NO");
    }
    return 0;
}

