        bool adj[26][26] = {};
        for (size_t i = 0; i + 1 < s.size(); i++) {
            int a = s[i] - 'a', b = s[i + 1] - 'a';
            adj[a][b] = adj[b][a] = true;
        }
        int deg[26] = {};
        bool bad = false;
        for (int u = 0; u < 26; u++)
            for (int v = 0; v < 26; v++)
                if (adj[u][v]) deg[u]++;
        for (int u = 0; u < 26; u++)
            if (deg[u] > 2) bad = true;
        if (bad) { puts("NO"); continue; }
        // Walk each path from an endpoint (deg <= 1); unvisited letters left over lie on a cycle.
        bool vis[26] = {};
        string res;
        for (int st = 0; st < 26; st++) {
            if (vis[st] || deg[st] > 1) continue;
            int prev = -1, cur = st;
            while (true) {
                res.push_back('a' + cur);
                vis[cur] = true;
                int nxt = -1;
                for (int v = 0; v < 26; v++)
                    if (adj[cur][v] && v != prev && !vis[v]) { nxt = v; break; }
                if (nxt < 0) break;
                prev = cur;
                cur = nxt;
            }
        }
        for (int u = 0; u < 26; u++)
            if (!vis[u]) bad = true;  // a cycle
        if (bad) { puts("NO"); continue; }
        printf("YES\n%s\n", res.c_str());
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, m;
        long long d;
        scanf("%d %d %lld", &n, &m, &d);
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        // Total = sum of chosen a_i - d * (last chosen index), since penalties telescope.
        // Fix the last chosen index j; pick up to m-1 other positive values from 1..j-1.
        priority_queue<long long, vector<long long>, greater<long long>> pq;  // top (m-1) positives
        long long S = 0, best = 0;
        for (int j = 1; j <= n; j++) {
            best = max(best, a[j] - d * j + S);
            if (m > 1 && a[j] > 0) {
                if ((int)pq.size() < m - 1) {
                    pq.push(a[j]);
                    S += a[j];
                } else if (a[j] > pq.top()) {
                    S += a[j] - pq.top();
                    pq.pop();
                    pq.push(a[j]);
                }
            }
        }
        printf("%lld\n", best);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        long long k;
        scanf("%d %lld", &n, &k);
        vector<long long> a(n);
        long long S = 0, mx = 0;
        for (auto &x : a) {
            scanf("%lld", &x);
            S += x;
            mx = max(mx, x);
        }
        // Deck size d is feasible iff some number of decks M >= max a_i has M*d in [S, S+k]
        // (buy cards to reach total M*d; each value appears at most M times).
        int best = 1;
        for (long long d = n; d >= 1; d--) {
            long long lo = max(mx, (S + d - 1) / d);
            long long hi = (S + k) / d;
            if (lo <= hi) { best = (int)d; break; }
        }
        printf("%d\n", best);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<pair<long long, long long>> p(n);  // (b, a)
    long long N = 0;
    for (auto &x : p) {
        scanf("%lld %lld", &x.second, &x.first);  // read a, then b
        N += x.second;
    }
    sort(p.begin(), p.end());  // by b ascending
    // An item is discounted iff it is bought at a position pos with pos > b_i (pos is 1-indexed).
    // Greedy over positions: an item becomes eligible at position b_i + 1; each eligible
    // position consumes one eligible item if any is waiting.
    long long pos = 1, pool = 0, matched = 0;
    for (auto &x : p) {
        long long b = x.first, a = x.second;
        long long e = min(b + 1, N + 1);
        long long gap = e - pos;
        long long take = min(pool, gap);
        matched += take;
        pool -= take;
        pos = e;
        pool += a;
    }
    long long take = min(pool, N + 1 - pos);
    matched += take;
    printf("%lld\n", 2 * N - matched);
    return 0;
}
